static String isolationName(int level) {
  if (level == Connection.TRANSACTION_READ_UNCOMMITTED) return "READ_UNCOMMITTED";
  if (level == Connection.TRANSACTION_READ_COMMITTED) return "READ_COMMITTED";
  if (level == Connection.TRANSACTION_REPEATABLE_READ) return "REPEATABLE_READ";
  if (level == Connection.TRANSACTION_SERIALIZABLE) return "SERIALIZABLE";
  return "NIEZNANY";
}

