static Connection borrow(List<Connection> pool) { return pool.remove(pool.size() - 1); }
static void giveBack(List<Connection> pool, Connection c) { pool.add(c); }
List<Connection> pool = new ArrayList<>(List.of(c1, c2, c3));
System.out.println("Przed: " + pool.size());
Connection borrowed = borrow(pool);
System.out.println("Po pozyczeniu: " + pool.size());
giveBack(pool, borrowed);
System.out.println("Po oddaniu: " + pool.size());

