class TimestampedConnection implements AutoCloseable {
  private final Connection conn; private final long openedAt = System.nanoTime();
  TimestampedConnection(Connection conn) { this.conn = conn; }
  public void close() throws SQLException {
    conn.close();
    System.out.println("Otwarte przez " + (System.nanoTime() - openedAt)/1_000_000 + "ms");
  }
}
