static Connection connectWithRetry(String url, int maxAttempts) throws SQLException {
  SQLException lastError = null;
  for (int i = 0; i < maxAttempts; i++) {
    try { return DriverManager.getConnection(url); }
    catch (SQLException e) { lastError = e; try { Thread.sleep(50); } catch (InterruptedException ignored) { } }
  }
  throw lastError;
}

