class ConnectionManager {
  private final List<Connection> connections = new ArrayList<>();
  private final String url; private final int n;
  ConnectionManager(String url, int n) { this.url = url; this.n = n; }
  void open() throws SQLException { for (int i = 0; i < n; i++) connections.add(DriverManager.getConnection(url)); }
  void closeAll() throws SQLException { for (Connection c : connections) c.close(); }
  List<Connection> getConnections() { return connections; }
}

